const call = $('Call first').first().json.results || [];
const cold = $('Going cold').first().json.results || [];
const days = (d) => d ? Math.floor((Date.now() - new Date(d)) / 864e5) : '?';
const text = ['Call first today:',
  ...(call.length ? call.map((c, i) => `${i + 1}. ${c.properties.company || c.properties.firstname} · ${c.properties.harvest_score}`) : ['(nobody new)']),
  '', 'Going cold (no activity 7+ days):',
  ...(cold.length ? cold.map(d => `- ${d.properties.dealname} · ${days(d.properties.notes_last_updated)} days`) : ['(none)'])].join('\n');
return [{ json: { text } }];
